//! FerroProve safe crate. Indexes become slice gets that return -100.
#![forbid(unsafe_code)]
#![allow(unused_variables, unused_mut, unused_assignments, unused_parens, unused_macros, dead_code, unreachable_code, non_upper_case_globals, non_camel_case_types, non_snake_case)]

macro_rules! at {
    ($buf:expr, $i:expr) => {
        match $buf.get($i as usize) {
            Some(v) => *v as i32,
            None => return -100,
        }
    };
}
macro_rules! put {
    ($buf:expr, $i:expr, $v:expr) => {{
        let __idx = ($i) as usize;
        let __val = $v;
        match $buf.get_mut(__idx) {
            Some(slot) => *slot = __val,
            None => return -100,
        }
    }};
}

pub fn crc8_populate_msb(table: &mut [u8], mut polynomial: i32) -> i32 {
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut msbit: i32 = ((128) & 255);
    let mut t: i32 = ((msbit) & 255);
    put!(table, 0, (0 as u8));
    i = 1;
    while i < 256 {
        t = ((((t as i32).wrapping_shl((1) as u32) ^ (if (t & msbit) != 0 { polynomial } else { 0 }))) & 255);
        j = 0;
        while j < i {
            put!(table, (i + j), ((at!(table, j) ^ t) as u8));
            j = (j + 1);
        }
        i = (i as i32).wrapping_mul(2);
    }
    0
}

pub fn crc8_populate_lsb(table: &mut [u8], mut polynomial: i32) -> i32 {
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut t: i32 = ((1) & 255);
    put!(table, 0, (0 as u8));
    i = (256 >> 1);
    while i != 0 {
        t = ((((((t) as u32).wrapping_shr((1) as u32) as i32) ^ (if (t & 1) != 0 { polynomial } else { 0 }))) & 255);
        j = 0;
        while j < 256 {
            put!(table, (i + j), ((at!(table, j) ^ t) as u8));
            j = (j + (2 as i32).wrapping_mul(i));
        }
        i = (i >> 1);
    }
    0
}

pub fn crc8(table: & [u8], pdata: & [u8], mut nbytes: i32, mut crc: i32) -> i32 {
    let mut __pdata_off: i32 = 0;
    while nbytes > 0 {
        nbytes = (nbytes as i32).wrapping_sub(1);
        crc = ((at!(table, ((crc ^ at!(pdata, __pdata_off)) & 255))) & 255);
        __pdata_off = (__pdata_off + 1);
    }
    return crc;
}

